<template>
  <div class="page-stack"><PageHeader :title="$t(&quot;Planning d’équipe&quot;)"><button class="btn btn-outline" :disabled="loading || busy" @click="load">{{ $t("Actualiser") }}</button></PageHeader><p class="field-hint">{{ $t("Préparez les gardes en UTC, puis publiez le planning. Les agents continuent de voir la dernière version publiée pendant vos modifications.") }}</p><p v-if="error" class="field-error" role="alert">{{ $t(error) }}</p><div class="form-grid"><label class="field"><span class="field-label">{{ $t("Équipe") }}</span><select v-model.number="teamId" class="input"><option v-for="team in teams" :key="team.id" :value="team.id">{{ team.name }}</option></select></label><label class="field"><span class="field-label">{{ $t("Début du planning") }}</span><input v-model="start" class="input" type="date" /></label><button class="btn btn-primary" :disabled="busy || !teamId || !start" @click="create">{{ $t("Créer un planning de 14 jours") }}</button></div><p v-if="loading" role="status">{{ $t("Chargement…") }}</p><p v-else-if="!error && !plans.length" class="muted">{{ $t("Aucun planning sur cette période.") }}</p><label v-if="plans.length" class="field"><span class="field-label">{{ $t("Planning affiché") }}</span><select v-model.number="planId" class="input"><option v-for="plan in plans" :key="plan.id" :value="plan.id">{{ plan.team_name }} · {{ plan.start }} · {{ $t(plan.published ? 'Publié' : 'Brouillon') }}</option></select></label><section v-if="plan" class="card section-card page-stack"><header><div><h2 class="card-title">{{ plan.team_name }} · {{ plan.start }}</h2><p class="field-hint">{{ $t("Version") }} {{ plan.revision }} · {{ $t(plan.published ? 'Publiée' : 'Modifications à publier') }}</p></div><div class="actions"><button class="btn btn-outline" :disabled="busy || !plan.can_manage" @click="edit(null)">{{ $t("Ajouter une garde") }}</button><button class="btn btn-outline" :disabled="busy || plan.shifts.length || plan.published_at" @click="rangeEdit = true; newStart = plan.start; newDays = plan.days">{{ $t("Modifier la période") }}</button><button class="btn btn-danger" :disabled="busy" @click="planDeletion = true; deletionReason = ''; dialogError = ''">{{ $t("Supprimer le planning") }}</button><button class="btn btn-primary" :disabled="busy || !plan.can_publish || plan.published || !plan.shifts.length" @click="publish">{{ $t("Publier") }}</button></div></header><p v-if="!plan.can_publish" class="field-hint">{{ $t("Votre droit de publication est désactivé pour cette équipe.") }}</p><div class="table-scroll"><table class="table"><thead><tr><th>{{ $t("Agent") }}</th><th>{{ $t("Début UTC") }}</th><th>{{ $t("Fin UTC") }}</th><th>{{ $t("Type") }}</th><th>{{ $t("Lieu") }}</th><th>{{ $t("Actions") }}</th></tr></thead><tbody><tr v-for="shift in plan.shifts" :key="shift.id"><td>{{ memberName(shift.user_id) }}</td><td>{{ stamp(shift.start) }}</td><td>{{ stamp(shift.end) }}</td><td><HourTag :kind="shift.kind" /></td><td>{{ shift.place }}</td><td><div class="actions"><button class="btn btn-outline btn-sm" :disabled="busy || !future(shift)" @click="edit(shift)">{{ $t("Modifier") }}</button><button class="btn btn-danger btn-sm" :disabled="busy || !future(shift)" @click="removal = shift">{{ $t("Supprimer") }}</button></div></td></tr></tbody></table></div><p v-if="!plan.shifts.length" class="muted">{{ $t("Aucune garde. Ajoutez les affectations des membres de cette équipe.") }}</p></section><SwapPanel can-review @changed="load" /><AbsencePanel can-review />
    <ModalDialog v-if="rangeEdit" :title="$t(&quot;Modifier la période du brouillon&quot;)" id="edit-plan-range" :busy="busy" @close="rangeEdit = false"><label class="field"><span class="field-label">{{ $t("Début") }}</span><input v-model="newStart" class="input" type="date" /></label><label class="field"><span class="field-label">{{ $t("Nombre de jours") }}</span><input v-model.number="newDays" class="input" type="number" min="1" max="31" /></label><p v-if="dialogError" class="field-error" role="alert">{{ $t(dialogError) }}</p><button class="btn btn-primary" :disabled="busy" @click="saveRange">{{ $t("Enregistrer") }}</button></ModalDialog>
    <ModalDialog v-if="planDeletion" :title="$t(&quot;Supprimer le planning&quot;)" id="delete-plan" :busy="busy" @close="planDeletion = false"><p>{{ $t("La suppression retire toutes les gardes de ce planning. Si le planning est publié, les agents seront informés.") }}</p><label class="field"><span class="field-label">{{ $t("Motif") }}</span><textarea v-model.trim="deletionReason" class="input" maxlength="500" /></label><p v-if="dialogError" class="field-error" role="alert">{{ $t(dialogError) }}</p><button class="btn btn-danger" :disabled="busy || !deletionReason" @click="erasePlan">{{ $t("Confirmer la suppression") }}</button></ModalDialog>
    <ModalDialog v-if="editing" :title="$t(form.id ? 'Modifier une garde' : 'Ajouter une garde')" id="edit-shift" :busy="busy" @close="editing = false"><form class="page-stack" @submit.prevent="save"><label class="field"><span class="field-label">{{ $t("Agent") }}</span><select v-model.number="form.user_id" class="input" required><option v-for="user in plan.members" :key="user.id" :value="user.id">{{ user.name || user.username }}</option></select></label><label class="field"><span class="field-label">{{ $t("Début UTC") }}</span><input v-model="form.start" class="input" type="datetime-local" required /></label><label class="field"><span class="field-label">{{ $t("Fin UTC") }}</span><input v-model="form.end" class="input" type="datetime-local" required /></label><label class="field"><span class="field-label">{{ $t("Type") }}</span><select v-model="form.kind" class="input"><option value="day">{{ $t("Jour") }}</option><option value="night">{{ $t("Nuit") }}</option><option value="oncall">{{ $t("Astreinte") }}</option><option value="leave">{{ $t("Congé prévu") }}</option><option value="rest">{{ $t("Repos prévu") }}</option></select></label><label class="field"><span class="field-label">{{ $t("Lieu") }}</span><input v-model.trim="form.place" class="input" maxlength="200" /></label><p v-if="dialogError" class="field-error" role="alert">{{ $t(dialogError) }}</p><button class="btn btn-primary" :disabled="busy || !form.user_id">{{ $t("Enregistrer") }}</button></form></ModalDialog>
    <ModalDialog v-if="removal" :title="$t(&quot;Supprimer cette garde&quot;)" id="delete-shift" :busy="busy" @close="removal = null"><p>{{ memberName(removal.user_id) }} · {{ stamp(removal.start) }} {{ $t("UTC") }}</p><p v-if="dialogError" class="field-error" role="alert">{{ $t(dialogError) }}</p><button class="btn btn-danger" :disabled="busy" @click="remove">{{ $t("Confirmer la suppression") }}</button></ModalDialog>
  </div>
</template>
<script>
import PageHeader from '../ui/PageHeader.vue'
import ModalDialog from '../ui/ModalDialog.vue'
import HourTag from '../ui/HourTag.vue'
import AbsencePanel from './AbsencePanel.vue'
import SwapPanel from './SwapPanel.vue'
import { auth } from '../../stores/auth'
import { listTeams } from '../../services/teamService'
import * as api from '../../services/workforceService'
import { toDateInput } from '../../utils/date'
import { addDays } from '../../utils/hours'
import { clockDate } from '../../utils/missingDeparture'
import { formatClockDate } from '../../utils/clockDate'
export default {
  name: 'TeamPlan', components: { PageHeader, ModalDialog, HourTag, AbsencePanel, SwapPanel },
  data() { return { teams: [], teamId: null, plans: [], planId: null, start: toDateInput(addDays(new Date(),15)), loading: false, busy: false, error: '', dialogError: '', editing: false, removal: null, rangeEdit: false, newStart: '', newDays: 14, planDeletion: false, deletionReason: '', version: 0, form: {} } },
  computed: { plan() { return this.plans.find(item => item.id === this.planId) } },
  watch: { start() { this.load() } }, created() { this.load() }, beforeUnmount() { this.version += 1 },
  methods: {
    stamp: formatClockDate, future(shift) { return clockDate(shift.start) > new Date() },
    memberName(id) { return this.plan?.members.find(user => user.id === id)?.name || this.plan?.members.find(user => user.id === id)?.username || `Agent ${id}` },
    async load() { const version = ++this.version; this.loading = true; this.error = ''; try { const [teams, plans] = await Promise.all([listTeams(), api.listPlans({ from: this.start, to: toDateInput(addDays(new Date(`${this.start}T00:00:00`),60)) })]); if (version === this.version) { this.teams = auth.user?.role === 'administrator' ? teams : teams.filter(team => team.manager?.id === auth.user?.id); this.teamId = this.teams.some(team => team.id === this.teamId) ? this.teamId : this.teams[0]?.id; this.plans = plans.filter(plan => plan.can_manage); this.planId = this.plans.some(plan => plan.id === this.planId) ? this.planId : this.plans[0]?.id } } catch (error) { if (version === this.version) this.error = error.message } finally { if (version === this.version) this.loading = false } },
    replace(plan) { const exists = this.plans.some(item => item.id === plan.id); this.plans = exists ? this.plans.map(item => item.id === plan.id ? plan : item) : [...this.plans,plan]; this.planId = plan.id },
    async run(action, dialog = false) { if (this.busy) return; this.busy = true; this.error = ''; this.dialogError = ''; try { this.replace(await action()); this.editing = false; this.removal = null; this.rangeEdit = false } catch (error) { if (dialog) this.dialogError = error.message; else this.error = error.message } finally { this.busy = false } },
    saveRange() { return this.run(() => api.updatePlan(this.plan.id,{revision:this.plan.revision,start:this.newStart,days:this.newDays}),true) },
    async erasePlan() { if (this.busy) return; const id = this.plan.id; this.busy = true; this.dialogError = ''; try { await api.deletePlan(id,this.plan.revision,this.deletionReason); this.plans = this.plans.filter(plan => plan.id !== id); this.planId = this.plans[0]?.id; this.planDeletion = false } catch (error) { this.dialogError = error.message } finally { this.busy = false } },
    create() { return this.run(() => api.createPlan(this.teamId,{ start: this.start, days: 14 })) },
    publish() { return this.run(() => api.publishPlan(this.plan.id,this.plan.revision)) },
    edit(shift) { this.dialogError = ''; this.form = shift ? { ...shift, start: formatClockDate(shift.start).replace(' ','T').slice(0,16), end: formatClockDate(shift.end).replace(' ','T').slice(0,16) } : { id: null, user_id: this.plan.members[0]?.id, start: `${this.plan.start}T08:00`, end: `${this.plan.start}T16:00`, kind: 'day', place: '' }; this.editing = true },
    save() { return this.run(() => api.saveShift(this.plan.id,this.form.id,{ ...this.form, revision: this.plan.revision, start: `${this.form.start}:00Z`, end: `${this.form.end}:00Z` }),true) },
    remove() { return this.run(() => api.deleteShift(this.plan.id,this.removal.id,this.plan.revision),true) },
  },
}
</script>
<style scoped>
header,.actions { display:flex;gap:12px;justify-content:space-between;flex-wrap:wrap;align-items:center; }
.form-grid { display:grid;grid-template-columns:1fr 1fr auto;gap:16px;align-items:end; }
.table-scroll { overflow-x:auto; }
@media(max-width:760px) { .form-grid { grid-template-columns:1fr; } }
</style>
